std::string quote(const std::string& value){std::ostringstream out;out<<'"';const char* digits="0123456789abcdef";for(unsigned char c:value){if(c=='"'||c=='\\')out<<'\\'<<static_cast<char>(c);else if(c<32)out<<"\\u00"<<digits[c/16]<<digits[c%16];else out<<static_cast<char>(c);}return out.str()+'"';}
void save(const fs::path& path,const std::string& value){std::ofstream out(path,std::ios::binary);out<<value;if(!out)throw std::runtime_error("cannot save coverage comparison evidence");}
std::string read(const fs::path& path,std::size_t limit=8*1024*1024){if(!fs::is_regular_file(path)||fs::file_size(path)>limit)throw std::runtime_error("missing or oversized coverage comparison input");std::ifstream in(path,std::ios::binary);std::string text((std::istreambuf_iterator<char>(in)),{});if(!in)throw std::runtime_error("cannot read comparison input");return text;}
std::string fingerprint(const std::string& text){std::uint64_t h=14695981039346656037ULL;for(unsigned char c:text){h^=c;h*=1099511628211ULL;}std::ostringstream out;out<<std::hex<<std::setw(16)<<std::setfill('0')<<h;return out.str();}
struct Material {bool directory=false;std::uintmax_t size=0;std::string hash;bool operator==(const Material&)const=default;};
using Materials=std::map<std::string,Material>;
Material material(const fs::path& path,const ScanContext& context,std::uintmax_t& total){
    if(fs::is_symlink(path))throw std::runtime_error("paired source inputs cannot contain symlinks");
    if(fs::is_directory(path))return {true,0,{}};if(!fs::is_regular_file(path))throw std::runtime_error("unsupported paired source input type");
    std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("cannot read paired source input");std::uint64_t h=14695981039346656037ULL;std::uintmax_t bytes=0;const auto size=fs::file_size(path);char buffer[65536];
    while(in){context.check();in.read(buffer,sizeof(buffer));const auto n=in.gcount();bytes+=static_cast<std::uintmax_t>(n);total+=static_cast<std::uintmax_t>(n);if(total>2ULL*1024*1024*1024)throw std::runtime_error("paired source inputs exceed 2 GiB");for(std::streamsize i=0;i<n;++i){h^=static_cast<unsigned char>(buffer[i]);h*=1099511628211ULL;}}
    if(!in.eof()||bytes!=size||fs::file_size(path)!=size)throw std::runtime_error("paired source input changed while reading");std::ostringstream hex;hex<<std::hex<<std::setw(16)<<std::setfill('0')<<h;return {false,bytes,hex.str()};
}
Materials inventory(const fs::path& root,const ScanContext& context){
    if(!fs::is_directory(root)||fs::is_symlink(root))throw std::runtime_error("paired source tree unavailable");Materials out;std::uintmax_t total=0;
    for(const auto& entry:fs::recursive_directory_iterator(root)){context.check();if(out.size()>=100000)throw std::runtime_error("paired source inputs exceed 100000 entries");if(!project_path_inside(entry.path(),root))throw std::runtime_error("paired source input escapes its copy");out.emplace(utf8_path(entry.path().lexically_relative(root)),material(entry.path(),context,total));}return out;
}
std::string manifest(const Materials& values){std::ostringstream out;for(const auto& [name,value]:values)out<<quote(name)<<'\t'<<(value.directory?"directory":"file")<<'\t'<<value.size<<'\t'<<value.hash<<'\n';return out.str();}
struct MaterialGuard {
    Materials original,patched;bool captured=false;std::string signature;fs::path record;const RepairPlan& plan;const ValidationInputs& snapshot;
    void capture(const fs::path& path,const ScanContext& context){if(captured)return;original=inventory(path,context);
        for(const auto& f:snapshot.files){const auto at=original.find(f.path);if(at==original.end()||at->second.directory||at->second.size!=f.size||"fnv1a64-v1:"+at->second.hash!=f.hash)throw std::runtime_error("frozen paired inputs differ from saved C/C++ snapshot");}
        patched=original;for(const auto& file:plan.files){const auto at=patched.find(file.file);if(at==patched.end()||at->second.directory)throw std::runtime_error("paired edit missing from input inventory");at->second.size=file.after.size();at->second.hash=fingerprint(file.after);}
        const auto text=manifest(original);signature="copied-input-content-v1:"+fingerprint(text);save(record/"original-inputs.tsv",text);save(record/"patched-inputs.tsv",manifest(patched));captured=true;
    }
    void verify(const fs::path& source,bool changed,const ScanContext& context)const{if(!captured||inventory(source,context)!=(changed?patched:original))throw std::runtime_error("paired copied inputs changed; source/build scripts/resources differ from frozen proposal");}
    bool original_inputs_match(const fs::path& root)const{if(!captured)return false;ScanContext uncancelled;std::uintmax_t bytes=0;try{for(const auto& [name,value]:original)if(material(root/from_utf8(name),uncancelled,bytes)!=value)return false;return true;}catch(...){return false;}}
};
bool step_passed(const BuildRun& run,const std::string& name){for(const auto& s:run.steps)if(s.name==name)return s.result.status=="passed";return false;}
bool completed_failure(const RepairTestCoverageEntry& entry){
    if(entry.tests_failed==0)return true;
    if(entry.coverage.notes_files<=0||entry.coverage.data_files!=entry.coverage.notes_files)return false;
    // gcov may not flush counters after a crash/timeout. Only CTest's ordinary
    // nonzero exit result is usable as a diagnostic failed observation.
    const auto text=read(from_utf8(entry.workspace)/"tests.xml");std::size_t at=0;int failures=0;
    while((at=text.find("<failure",at))!=std::string::npos){const auto end=text.find('>',at);if(end==std::string::npos||end-at>65536)return false;const auto tag=text.substr(at,end-at+1);if(tag.find("message=\"Failed\"")==std::string::npos)return false;++failures;at=end+1;}
    return failures==entry.tests_failed;
}
bool complete_measurements(const CoverageObservation& observation){
    if(observation.coverage.status!="collected"||observation.test_coverage.entries.empty()||(observation.test_coverage.status!="collected"&&observation.test_coverage.status!="incomplete"))return false;
    bool suite=false;for(const auto& step:observation.build.steps)if(step.name=="test")suite=step.tests_total>0&&step.tests_skipped==0&&step.tests_failed>=0&&((step.result.status=="passed"&&step.tests_failed==0)||(step.result.status=="failed"&&step.tests_failed>0));
    return suite&&std::all_of(observation.test_coverage.entries.begin(),observation.test_coverage.entries.end(),[](const auto& e){return e.coverage.status=="collected"&&e.tests_total>0&&e.tests_failed>=0&&e.tests_not_run==0&&e.tests_disabled==0&&e.tests_skipped==0&&(e.status=="collected"||(e.status=="tests_incomplete"&&e.tests_failed>0))&&completed_failure(e);});
}
using Lines=std::map<std::pair<std::string,int>,bool>;
Lines lines(const RepairCoverage& coverage){Lines result;for(const auto& f:coverage.files)for(const auto& [n,hit]:f.lines)result[{f.file,n}]=hit;return result;}
bool all_groups_match(const CoverageObservation& o){Lines combined;for(const auto& e:o.test_coverage.entries)for(const auto& [line,hit]:lines(e.coverage))combined[line]=combined[line]||hit;return combined==lines(o.coverage);}
std::size_t line_observations(const CoverageObservation& o){std::size_t count=0;for(const auto& f:o.coverage.files)count+=f.lines.size();for(const auto& e:o.test_coverage.entries)for(const auto& f:e.coverage.files)count+=f.lines.size();return count;}
bool unchanged_cpp(const ValidationInputs& saved,const fs::path& root,const BuildOptions& options){try{auto scan=configured_scan_options(root,decode_config(saved.analysis.configuration));scan.context={};scan.ignored_paths=options.copy_excludes;const auto now=scan_project(root,scan);if(!now.diagnostics.empty()||now.files.size()!=saved.files.size())return false;for(std::size_t n=0;n<now.files.size();++n)if(now.files[n].path!=saved.files[n].path||now.files[n].hash!=saved.files[n].hash||now.files[n].size!=saved.files[n].size)return false;return true;}catch(...){return false;}}
fs::path output_directory(const fs::path& output,const fs::path& root){if(output.empty()||project_path_inside(output,root))throw std::invalid_argument("coverage comparison output must be outside original project");fs::create_directories(output);const auto base=fs::canonical(output);if(project_path_inside(base,root))throw std::invalid_argument("comparison output resolves inside original project");for(unsigned n=0;n<100;++n){auto dir=base/("cmp-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+'-'+std::to_string(n));if(fs::create_directory(dir))return dir;}throw std::runtime_error("cannot allocate unique comparison workspace");}
std::uintmax_t bytes_used(const fs::path& root,const ScanContext& context){std::uintmax_t bytes=0;std::size_t count=0;for(const auto& e:fs::recursive_directory_iterator(root)){context.check();if(++count>2000000||e.is_symlink())throw std::runtime_error("unsupported or excessive comparison artifacts");if(e.is_regular_file())bytes+=e.file_size();}return bytes;}
void replace_root(std::string& text,const std::string& root,const std::string& token){
    for(auto value:std::vector<std::string>{root,[&]{auto s=root;std::replace(s.begin(),s.end(),'/','\\');return s;}()}){
        const auto encoded=quote(value);const auto prefix=encoded.substr(1,encoded.size()-2);for(const auto& sep:std::vector<std::string>{"/","\\\\"}){const auto from=prefix+sep,to=token+sep;std::size_t at=0;while((at=text.find(from,at))!=std::string::npos){text.replace(at,from.size(),to);at+=to.size();}}
        std::size_t at=0;const auto to=quote(token);while((at=text.find(encoded,at))!=std::string::npos){text.replace(at,encoded.size(),to);at+=to.size();}
    }
}
