std::string normalized_test_catalog(const fs::path& metadata,const fs::path& source,const fs::path& build){
    const auto text=read(metadata);if(text.find("$SOURCE")!=std::string::npos||text.find("$BUILD")!=std::string::npos)throw std::runtime_error("test catalog contains reserved normalization marker");sqlite3* db=nullptr;if(sqlite3_open(":memory:",&db)!=SQLITE_OK){if(db)sqlite3_close(db);throw std::runtime_error("cannot open catalog normalizer");}std::unique_ptr<sqlite3,decltype(&sqlite3_close)> guard(db,sqlite3_close);sqlite3_stmt* raw=nullptr;
    const char* sql="SELECT json_extract(value,'$.name'),json_extract(value,'$.command'),json_extract(value,'$.properties') FROM json_each(?1,'$.tests') ORDER BY json_extract(value,'$.name')";
    if(sqlite3_prepare_v2(db,sql,-1,&raw,nullptr)!=SQLITE_OK)throw std::runtime_error("catalog normalization requires SQLite JSON support");std::unique_ptr<sqlite3_stmt,decltype(&sqlite3_finalize)> statement(raw,sqlite3_finalize);sqlite3_bind_text(raw,1,text.data(),static_cast<int>(text.size()),SQLITE_TRANSIENT);std::ostringstream out;std::size_t count=0;int code;
    while((code=sqlite3_step(raw))==SQLITE_ROW){if(++count>256)throw std::runtime_error("paired catalog exceeds 256 tests");for(int n=0;n<3;++n){const auto* value=sqlite3_column_text(raw,n);if(!value)throw std::runtime_error("paired catalog lacks name/command/properties");std::string s(reinterpret_cast<const char*>(value),static_cast<std::size_t>(sqlite3_column_bytes(raw,n)));if(n){replace_root(s,utf8_path(source),"$SOURCE");replace_root(s,utf8_path(build),"$BUILD");}out<<s.size()<<':'<<s<<'\n';}}
    if(code!=SQLITE_DONE||count==0)throw std::runtime_error("invalid or empty paired catalog");return out.str();
}
RepairCoverageComparison compare_repair_coverage(const fs::path& input,const fs::path& database,std::vector<RepairCandidate> components,BuildOptions options,unsigned rounds){
    if(rounds<2||rounds>5)throw std::invalid_argument("paired coverage requires 2..5 rounds per version");if(components.empty()||components.size()>16)throw std::invalid_argument("paired coverage requires 1..16 proposed edits");if(options.coverage_test_limit<1||options.coverage_test_limit>256)throw std::invalid_argument("paired coverage test limit must be 1..256");
    std::string payload,manifest_name,id;
    if(components.size()==1){payload=encode_repair_candidate(components.front());manifest_name="candidate.cgfix";id=components.front().id;}else{auto set=compose_repairs(std::move(components));components=std::move(set.components);payload=encode_repair_set({set.id,components});manifest_name="repair.cgset";id=set.id;}
    const auto plan=make_repair_plan(components);const auto root=fs::canonical(input);SqliteDatabase db(database,true);const auto snapshot=db.validation_inputs(utf8_path(root));const auto& first=components.front();
    if(!snapshot.id||fs::canonical(from_utf8(first.root))!=root||snapshot.id!=first.scan_id||snapshot.analysis.configuration!=first.configuration)throw std::invalid_argument("comparison requires current project/scan/configuration");
    for(const auto& c:components)if(std::none_of(snapshot.analysis.issues.begin(),snapshot.analysis.issues.end(),[&](const auto& i){return i.rule_id==c.edit.rule_id&&i.file==c.edit.file&&i.line==c.edit.line&&i.column==c.edit.column;}))throw std::invalid_argument("comparison component is not an active saved issue");
    for(const auto& file:plan.files)if(read(root/from_utf8(file.file),2*1024*1024)!=file.before)throw std::invalid_argument("comparison requires exact original source bytes");
    const auto directory=output_directory(options.output_directory,root);RepairCoverageComparison result;result.id=id;result.workspace=utf8_path(directory);result.rounds=rounds;result.status="running";save(directory/manifest_name,payload);std::string diff;for(const auto& f:plan.files)diff+=repair_file_diff(f.file,f.before,f.after);save(directory/"candidate.diff",diff);
    for(unsigned n=0;n<rounds;++n)for(bool patched:n%2?std::vector<bool>{true,false}:std::vector<bool>{false,true}){CoverageObservation o;o.round=n;o.version=patched?"patched":"original";o.workspace=utf8_path(directory/("r"+std::to_string(n)+(patched?"p":"o")));result.observations.push_back(std::move(o));}
    ScanContext context;context.control=options.control;auto persist=[&]{save(directory/"comparison.json",repair_coverage_comparison_json(result));};persist();MaterialGuard materials{{},{},false,{},directory,plan,snapshot};std::size_t current=0,observed_lines=0;
    try{
        for(;current<result.observations.size();++current){context.check();auto& o=result.observations[current];const bool changed=o.version=="patched";const auto side=from_utf8(o.workspace);if(!fs::create_directory(side))throw std::runtime_error("paired observation directory already exists");o.status="running";persist();if(options.progress)options.progress(changed?"repair_compare_patched":"repair_compare_original");context.check();
            const auto parent=options.control,child=std::make_shared<ScanControl>();auto run_options=options;run_options.control=child;run_options.defer_commit_fence=true;run_options.keep_unpatched_copy=true;run_options.configure_only=false;run_options.collect_coverage=true;run_options.collect_test_coverage=true;run_options.copy_replacements.clear();
            std::jthread forward([parent,child](std::stop_token stop){while(!stop.stop_requested()){if(parent&&parent->state()==ScanControl::State::cancel_requested)child->request_cancel();std::this_thread::sleep_for(std::chrono::milliseconds(10));}});
            const auto previous=run_options.before_configure;run_options.before_configure=[&,previous,changed,child](const fs::path& work){ScanContext c;c.control=child;materials.capture(work/"baseline-source",c);if(previous)previous(work);materials.verify(work/"baseline-source",false,c);materials.verify(work/"source",changed,c);};
            try{
                if(changed){run_options.output_directory=side;auto validation=validate_repair_plan(root,database,plan,id,run_options,[&]{save(side/manifest_name,payload);save(side/"candidate.diff",diff);return side;});o.validation_record=utf8_path(side/"validation.json");o.standard_validation_passed=validation.gates_passed;o.build=std::move(validation.build);o.coverage=std::move(validation.coverage);o.test_coverage=std::move(validation.test_coverage);o.error=std::move(validation.error);}
                else{run_options.output_directory=side/"b";prepare_repair_coverage(run_options,side/"coverage");o.build=build_and_test(root,database,run_options);child->check();if(step_passed(o.build,"configure")&&step_passed(o.build,"build")){auto target=first;o.coverage=collect_repair_coverage(o.build,target,snapshot,run_options,side/"coverage");auto targets=repair_plan_targets(plan);for(auto& t:targets){t.revised_line=t.line;t.revised_column=t.column;}o.test_coverage=collect_repair_test_coverage(o.build,targets,snapshot,o.coverage,run_options,from_utf8(o.build.workspace)/"test-coverage");}}
                child->check();context.check();if(o.build.scan_id!=snapshot.id||!o.build.source_unchanged)throw std::runtime_error("saved scan or original C/C++ inputs changed during comparison");
                materials.verify(from_utf8(o.build.workspace)/"source",changed,context);materials.verify(from_utf8(o.build.workspace)/"baseline-source",false,context);o.material_verified=true;
                if(!complete_measurements(o))throw std::runtime_error("paired measurement incomplete; inspect build, aggregate and per-test records");o.normalized_catalog=normalized_test_catalog(from_utf8(o.test_coverage.workspace)/"tests.json",from_utf8(o.build.workspace)/"source",from_utf8(o.build.workspace)/"build");o.catalog_signature="ctest-logical-v1:"+fingerprint(o.normalized_catalog);save(side/"normalized-tests.txt",o.normalized_catalog);o.all_group_line_union_matches_aggregate=all_groups_match(o);o.status="collected";observed_lines+=line_observations(o);if(observed_lines>1000000)throw std::runtime_error("paired measurements exceed 1000000 observed line records");
            }catch(const ScanCancelled&){o.status="cancelled";throw;}catch(const std::exception& e){o.status="failed";o.error=e.what();}
            forward.request_stop();child->finish();result.input_signature=materials.signature;persist();if(options.progress)options.progress("repair_compare_observation_complete");context.check();
            if(observed_lines>1000000)throw std::runtime_error("paired measurements exceed 1000000 observed line records; remaining observations not run");
            if(!unchanged_cpp(snapshot,root,options)||!materials.original_inputs_match(root))throw std::runtime_error("original C/C++ or known copied inputs changed; remaining comparisons stopped");
            if(bytes_used(directory,context)>2ULL*1024*1024*1024)throw std::runtime_error("comparison artifacts exceed 2 GiB; remaining observations not run");
        }
        result.original_cpp_unchanged=unchanged_cpp(snapshot,root,options);result.known_original_inputs_unchanged=materials.original_inputs_match(root);summarize_repair_coverage(result,plan,context);
    }catch(const ScanCancelled& e){result.status="cancelled";result.error=e.what();result.ready_for_review=false;if(current<result.observations.size()&&result.observations[current].status=="running")result.observations[current].status="cancelled";}
    catch(const std::exception& e){result.status="failed";result.error=e.what();result.ready_for_review=false;if(current<result.observations.size()&&result.observations[current].status=="running"){result.observations[current].status="failed";result.observations[current].error=e.what();}}
    result.original_cpp_unchanged=unchanged_cpp(snapshot,root,options);result.known_original_inputs_unchanged=materials.original_inputs_match(root);result.input_signature=materials.signature;
    if(!result.original_cpp_unchanged||(materials.captured&&!result.known_original_inputs_unchanged)){result.ready_for_review=false;if(result.status!="cancelled")result.status="source_changed";}
    if(db.latest_scan_id(utf8_path(root))!=snapshot.id){result.ready_for_review=false;if(result.status!="cancelled")result.status="stale_snapshot";result.error+="\nSaved scan changed during paired comparison; regenerate proposal.";}
    if(options.control)try{options.control->begin_commit();}catch(const ScanCancelled&){result.status="cancelled";result.ready_for_review=false;}
    persist();save(directory/"README.txt","Paired coverage is diagnostic evidence, not repair correctness. Each round uses fresh original/patched copies; ordering alternates. Only byte-coordinate-mapped unchanged lines are compared. Modified lines are listed separately. Failed original tests remain failures. Review all validation records and comparison.json. Input content fingerprints are not signatures.\n");return result;
}
std::string repair_coverage_comparison_json(const RepairCoverageComparison& r){
    std::ostringstream out;auto flag=[&](const char* name,bool value){out<<",\n  "<<quote(name)<<": "<<(value?"true":"false");};out<<"{\n  \"format\": \"CodeGuardCoverageComparison 1\",\n  \"id\": "<<quote(r.id)<<",\n  \"status\": "<<quote(r.status)<<",\n  \"workspace\": "<<quote(r.workspace)<<",\n  \"error\": "<<quote(r.error)<<",\n  \"input_signature\": "<<quote(r.input_signature)<<",\n  \"rounds_per_version\": "<<r.rounds<<",\n  \"correctness\": \"not_assessed\"";
    flag("comparison_complete",r.comparison_complete);flag("coverage_stable",r.coverage_stable);flag("tests_stable",r.tests_stable);flag("catalogs_match",r.catalogs_match);flag("tools_match",r.tools_match);flag("all_materials_verified",r.all_materials_verified);flag("all_patched_validations_passed",r.all_patched_validations_passed);flag("ready_for_review",r.ready_for_review);flag("original_cpp_unchanged",r.original_cpp_unchanged);flag("known_original_inputs_unchanged",r.known_original_inputs_unchanged);out<<",\n  \"observations\": [";
    for(std::size_t n=0;n<r.observations.size();++n){if(n)out<<',';const auto& o=r.observations[n];out<<"{\"round\": "<<o.round<<", \"version\": "<<quote(o.version)<<", \"status\": "<<quote(o.status)<<", \"workspace\": "<<quote(o.workspace)<<", \"error\": "<<quote(o.error)<<", \"build_run_id\": "<<o.build.id<<", \"scan_id\": "<<o.build.scan_id<<", \"build_status\": "<<quote(o.build.status)<<", \"validation_record\": "<<quote(o.validation_record)<<", \"coverage_record\": "<<quote(o.coverage.workspace.empty()?"":o.coverage.workspace+"/summary.json")<<", \"test_coverage_record\": "<<quote(o.test_coverage.workspace.empty()?"":o.test_coverage.workspace+"/summary.json")<<", \"catalog_signature\": "<<quote(o.catalog_signature)<<", \"gcov_version\": "<<quote(o.coverage.tool_version)<<", \"ctest_version\": "<<quote(o.test_coverage.ctest_version)<<", \"material_verified\": "<<(o.material_verified?"true":"false")<<", \"standard_validation_passed\": "<<(o.standard_validation_passed?"true":"false")<<", \"all_group_line_union_matches_aggregate\": "<<(o.all_group_line_union_matches_aggregate?"true":"false")<<", \"suite_steps\": [";bool comma=false;for(const auto& s:o.build.steps)if(s.name=="configure"||s.name=="build"||s.name=="test"){if(comma)out<<',';comma=true;out<<"{\"stage\": "<<quote(s.name)<<", \"status\": "<<quote(s.result.status)<<", \"tests_total\": "<<s.tests_total<<", \"tests_failed\": "<<s.tests_failed<<", \"tests_skipped\": "<<s.tests_skipped<<'}';}out<<"]}";}
    out<<"],\n  \"groups\": [";auto history=[&](const CoverageLineHistory& h){out<<"{\"state\": "<<quote(h.state)<<", \"observations\": "<<h.observations<<", \"instrumented\": "<<h.instrumented<<", \"recorded\": "<<h.recorded<<'}';};
    for(std::size_t n=0;n<r.groups.size();++n){if(n)out<<',';const auto& g=r.groups[n];out<<"{\"name\": "<<quote(g.name)<<", \"diagnostic_only\": "<<(g.diagnostic_only?"true":"false")<<", \"selected_tests\": [";for(std::size_t i=0;i<g.selected_tests.size();++i){if(i)out<<',';out<<quote(g.selected_tests[i]);}out<<"], \"files\": [";for(std::size_t i=0;i<g.files.size();++i){if(i)out<<',';const auto& f=g.files[i];out<<"{\"file\": "<<quote(f.file)<<", \"lines\": [";for(std::size_t j=0;j<f.lines.size();++j){if(j)out<<',';const auto& l=f.lines[j];out<<"{\"original_line\": "<<l.original_line<<", \"patched_line\": "<<l.patched_line<<", \"mapping\": "<<quote(l.mapping)<<", \"transition\": "<<quote(l.transition)<<", \"original\": ";history(l.original);out<<", \"patched\": ";history(l.patched);out<<'}';}out<<"]}";}out<<"]}";}out<<"]\n}\n";return out.str();
}
